def nthUglyNumber(n):
    ugly = [1]
    a = b = c = 0
    while len(ugly) < n:
        x2, x3, x5 = ugly[a] * 2, ugly[b] * 3, ugly[c] * 5
        nxt = min(x2, x3, x5)
        ugly.append(nxt)
        if nxt == x2:
            a += 1
        if nxt == x3:
            b += 1
        if nxt == x5:
            c += 1
    return ugly[n - 1]
